  {id:'reba2000',authors:'Hignett and McAtamney',year:'2000',title:'Rapid Entire Body Assessment (REBA)',url:'https://doi.org/10.1016/S0003-6870(99)00039-3',scope:'Observer screening method for whole-body postural exposure; not a clinical diagnosis.',verification:'DOI and bibliographic identity verified.'}
