const baseReliability = {
  display: 'Calibrate the instrument, preserve measurement geometry and settings, repeat readings, and report repeatability plus uncertainty rather than assuming the display is stable.',
  ergonomic: 'Standardize posture, personal equipment, task, and rater training; repeat representative trials and assess rater agreement or within-person repeatability as applicable.',
  behavior: 'Predefine events and success rules, synchronize data sources, repeat comparable trials, and assess inter-rater agreement for coded outcomes.'
};

function measure(x) {
  const family = x.family || 'display';
  return {
    id:x.id,
    name:x.name,
    constructs:x.constructs,
    family,
    definition:x.definition,
    operationalization:x.operationalization,
    units:x.units,
    timing:x.timing || (family === 'display' ? 'bench-test' : 'during-task'),
    modality:x.modality || (family === 'display' ? ['calibrated-instrument'] : ['observer','event-log']),
    reliability:{published:null,status:'protocol-specific',assessment:x.reliability || baseReliability[family] || baseReliability.behavior},
    validity:{basis:x.basis || 'Direct engineering or task-performance operationalization when the test condition matches the intended claim.',limitations:x.limitations || 'Results depend on the exact task, geometry, equipment, environment, criterion, and instrumentation; transfer requires a documented equivalence argument.'},
    aggregation:x.aggregation || 'Report by configuration, test condition, eye point or participant, and task; retain the underlying distribution and worst-case condition.',
    analysis:x.analysis || 'Predefine the applicable criterion and uncertainty treatment; report condition-specific estimates and failures, not only a pooled mean.',
    smallN:x.smallN || 'Use repeated calibrated observations or representative-user case evidence; do not claim population accommodation or rare-event rates from a small convenience sample.',
    sourceIds:x.sourceIds,
    context:x.context || 'Record aircraft/simulator, mission phase, viewing geometry, illumination, vibration, personal equipment, configuration, task, and applicable requirement.',
    evidenceStatus:x.evidenceStatus || 'source-backed-candidate-measure',
    applications:x.applications
  };
}

